CREATE OR REPLACE FUNCTION public.hrm_employee_scope_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.company_id IS NOT NULL THEN IF NOT EXISTS(SELECT 1 FROM public.company_members WHERE user_id=NEW.profile_id AND company_id=NEW.company_id) THEN RAISE EXCEPTION 'Link the user to this company in User Management first'; END IF; IF NEW.branch_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.hr_branches WHERE id=NEW.branch_id AND company_id=NEW.company_id) THEN RAISE EXCEPTION 'Employee branch must belong to the company'; END IF; IF NEW.department_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.hr_departments WHERE id=NEW.department_id AND company_id=NEW.company_id) THEN RAISE EXCEPTION 'Employee department must belong to the company'; END IF; IF NEW.designation_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.hr_designations WHERE id=NEW.designation_id AND company_id=NEW.company_id) THEN RAISE EXCEPTION 'Employee designation must belong to the company'; END IF; END IF; IF TG_OP='UPDATE' AND NEW.company_id IS DISTINCT FROM OLD.company_id AND (EXISTS(SELECT 1 FROM public.hr_attendance WHERE employee_id=OLD.id) OR EXISTS(SELECT 1 FROM public.hr_leave_requests WHERE employee_id=OLD.id) OR EXISTS(SELECT 1 FROM public.hr_payroll WHERE employee_id=OLD.id)) THEN RAISE EXCEPTION 'Company cannot change while employee HR history exists'; END IF; RETURN NEW; END $$;
CREATE TRIGGER hr_employee_scope BEFORE INSERT OR UPDATE ON public.hr_employees FOR EACH ROW EXECUTE FUNCTION public.hrm_employee_scope_guard();
CREATE OR REPLACE FUNCTION public.hrm_audience_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE x text; BEGIN FOR x IN SELECT jsonb_array_elements_text(coalesce(NEW.details->'employee_ids','[]')) LOOP IF NOT EXISTS(SELECT 1 FROM public.hr_employees WHERE id=x::uuid AND company_id=NEW.company_id) THEN RAISE EXCEPTION 'Audience employee must belong to the record company'; END IF; END LOOP; FOR x IN SELECT jsonb_array_elements_text(coalesce(NEW.details->'role_ids','[]')) LOOP IF NOT EXISTS(SELECT 1 FROM public.access_roles WHERE id=x::uuid) THEN RAISE EXCEPTION 'Select an existing permission role'; END IF; END LOOP; IF NEW.details->>'audience'='employees' AND jsonb_array_length(coalesce(NEW.details->'employee_ids','[]'))=0 THEN RAISE EXCEPTION 'Select at least one employee'; END IF; IF NEW.details->>'audience'='roles' AND jsonb_array_length(coalesce(NEW.details->'role_ids','[]'))=0 THEN RAISE EXCEPTION 'Select at least one authorized role'; END IF; IF nullif(NEW.details->>'organizer_id','') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.hr_employees WHERE id=(NEW.details->>'organizer_id')::uuid AND company_id=NEW.company_id) THEN RAISE EXCEPTION 'Organizer must belong to the meeting company'; END IF; RETURN NEW; END $$;
CREATE TRIGGER hr_meeting_audience BEFORE INSERT OR UPDATE ON public.hr_meetings FOR EACH ROW EXECUTE FUNCTION public.hrm_audience_guard();
CREATE TRIGGER hr_schedule_audience BEFORE INSERT OR UPDATE ON public.hr_schedules FOR EACH ROW EXECUTE FUNCTION public.hrm_audience_guard();
CREATE TRIGGER hr_announcement_audience BEFORE INSERT OR UPDATE ON public.hr_announcements FOR EACH ROW EXECUTE FUNCTION public.hrm_audience_guard();
CREATE TRIGGER hr_document_audience BEFORE INSERT OR UPDATE ON public.hr_documents FOR EACH ROW EXECUTE FUNCTION public.hrm_audience_guard();
CREATE POLICY hr_branch_hr_read ON public.hr_branches FOR SELECT TO authenticated USING(public.hrm_allowed('hr_attendance','view',company_id) OR public.hrm_allowed('hr_leave','view',company_id) OR public.hrm_allowed('hr_payroll','view',company_id) OR public.hrm_allowed('hr_meeting','view',company_id) OR public.hrm_allowed('hr_calendar','view',company_id) OR public.hrm_allowed('hr_document','view',company_id) OR public.hrm_allowed('hr_announcement','view',company_id) OR public.hrm_allowed('hr_holiday','view',company_id));
CREATE POLICY hr_department_hr_read ON public.hr_departments FOR SELECT TO authenticated USING(public.hrm_allowed('hr_attendance','view',company_id) OR public.hrm_allowed('hr_leave','view',company_id) OR public.hrm_allowed('hr_payroll','view',company_id) OR public.hrm_allowed('hr_meeting','view',company_id) OR public.hrm_allowed('hr_designation','view',company_id) OR public.hrm_allowed('hr_announcement','view',company_id) OR public.hrm_allowed('hr_document','view',company_id));
CREATE OR REPLACE FUNCTION public.hrm_org_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.hr_audit_logs(entity_type,entity_id,company_id,action,before_data,after_data) VALUES(CASE TG_TABLE_NAME WHEN 'hr_branches' THEN 'hr_branch' ELSE 'hr_designation' END,coalesce(NEW.id,OLD.id),coalesce(NEW.company_id,OLD.company_id),lower(TG_OP),CASE WHEN TG_OP<>'INSERT' THEN to_jsonb(OLD) END,CASE WHEN TG_OP<>'DELETE' THEN to_jsonb(NEW) END); IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER hr_branch_audit AFTER INSERT OR UPDATE OR DELETE ON public.hr_branches FOR EACH ROW EXECUTE FUNCTION public.hrm_org_audit();
CREATE TRIGGER hr_designation_audit AFTER INSERT OR UPDATE OR DELETE ON public.hr_designations FOR EACH ROW EXECUTE FUNCTION public.hrm_org_audit();